def detectar_encoding_escape(texto: str) -> str | None:
    """Retorna 'utf-16' se encontrar sequências \\uXXXX no texto."""
    import re
    if re.search(r'\\u[0-9a-fA-F]{4}', texto):
        return 'utf-16'
    return None

@staticmethod
def _detectar_encoding(dados: bytes) -> str:
    """Heurística: tenta decodificar como UTF-8, retorna cp1252 se falhar."""
    try:
        dados.decode('utf-8')
        return 'utf-8'
    except UnicodeDecodeError:
        return 'cp1252'
